class Solution {
    public int arithmeticTriplets(int[] nums, int diff) {
        Set<Integer> st = new HashSet<>();
        for (int x : nums) st.add(x);
        int ans = 0;
        for (int x : nums)
            if (st.contains(x + diff) && st.contains(x + 2 * diff)) ans++;
        return ans;
    }
}

